void isolation_phase_failure(const char* role, const char* phase) noexcept {
  FILETIME created{}, exited{}, kernel{}, user{};
  if (!GetProcessTimes(GetCurrentProcess(), &created, &exited, &kernel, &user)) return;
  const auto actual_creation = (static_cast<std::uint64_t>(created.dwHighDateTime) << 32U) | created.dwLowDateTime;
  if (!actual_creation) return;
  char bytes[640]{};
  const int length = std::snprintf(bytes, sizeof(bytes),
      "{\"schema\":\"soui.reference-agent-isolation-phase/1\",\"case\":\"page-isolation\",\"role\":\"%s\","
      "\"phase\":\"%s\",\"pid\":\"%lu\",\"creationFileTime\":\"%llu\"}\n",
      role, phase, static_cast<unsigned long>(GetCurrentProcessId()), static_cast<unsigned long long>(actual_creation));
  if (length <= 0 || static_cast<std::size_t>(length) >= sizeof(bytes)) return;
  DWORD written{};
  (void)WriteFile(GetStdHandle(STD_ERROR_HANDLE), bytes, static_cast<DWORD>(length), &written, nullptr);
}
